import helmet from 'helmet';

/**
 * Helmet Security Middleware Configuration
 * Hardens HTTP headers to protect against common web vulnerabilities (XSS, clickjacking, MIME-sniffing).
 */
export const helmetMiddleware = helmet({
  // Allows PDFs, XMLs and Danfe generated by backend to be fetched/rendered cross-origin in frontend iframe/blobs
  crossOriginResourcePolicy: { policy: 'cross-origin' },
  crossOriginEmbedderPolicy: false,
  // Disable CSP header for pure REST API backend so it doesn't conflict with PDF previews or client tools
  contentSecurityPolicy: false,
  // Hide Express signature
  hidePoweredBy: true,
  // Standard frameguard (deny embedding except if explicitly allowed)
  frameguard: { action: 'sameorigin' },
  // Prevent MIME-type sniffing
  noSniff: true,
  // Referrer Policy
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
});
